<style>
/* Layout: OFF+BRAND-style services page — fixed glossy orb + giant "SOLUÇÕES + WORK" behind, two-column card board on top (open service left, sticky; other services right), bottom-right menu button. Single dark look by choice. */
:root{
  --bg:#141019; --card:linear-gradient(125deg,rgba(96,37,225,.12),rgba(49,22,78,.2)),rgba(18,19,22,.66); --card-hover:var(--card); --line:rgba(255,255,255,.10);
  --fg:#EFEAF6; --muted:#BDB4CC; --accent:#C4A8FF; --pink:#FF8FCB;
  --display:"Space Grotesk","Helvetica Neue",Arial,sans-serif;
  --body:"Nunito",system-ui,sans-serif;
  --pad:clamp(16px,3.4vw,48px);
  --ease:cubic-bezier(.22,1,.36,1);
  color-scheme:dark;
}
*{box-sizing:border-box}
html{background:#121316}body{background:transparent;color:var(--fg);font-family:var(--body);overflow-x:hidden}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
:focus-visible{outline:2px solid var(--accent);outline-offset:3px}

/* Fixed background: orb + giant words */
.bgfx{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden}
.orb{position:absolute;left:-10vw;top:calc(12vh + 64px + 5.5vw);width:min(78vw,1100px);aspect-ratio:1;border-radius:50%;
  background:
    radial-gradient(circle at 62% 30%, rgba(255,255,255,.95) 0%, rgba(255,255,255,0) 22%),
    radial-gradient(circle at 30% 60%, #ff5fa2 0%, rgba(255,95,162,0) 45%),
    radial-gradient(circle at 70% 70%, #7c5cff 0%, rgba(124,92,255,0) 50%),
    radial-gradient(circle at 45% 45%, #ffb3d9 0%, #c86bff 45%, #5b2fd6 75%, #2a1170 100%);
  filter:saturate(1.15);
  animation:drift 18s ease-in-out infinite alternate}
.orb::after{content:"";position:absolute;inset:-6%;border-radius:50%;background:radial-gradient(circle,rgba(200,140,255,.35),transparent 65%);filter:blur(40px)}
.fluid{position:absolute;inset:0;width:100%;height:100%;display:block}
.gl .orb{visibility:hidden;animation:none}
.gl .words{visibility:hidden}
.orb2{position:absolute;right:-18vw;bottom:-30vh;width:60vw;aspect-ratio:1;border-radius:50%;
  background:radial-gradient(circle at 40% 40%,rgba(255,143,203,.55),rgba(124,92,255,.25) 45%,transparent 70%);filter:blur(30px);animation:drift2 22s ease-in-out infinite alternate}
@keyframes drift{0%{transform:translate(0,0) rotate(0)}50%{transform:translate(6vw,4vh) rotate(25deg)}100%{transform:translate(-3vw,8vh) rotate(-15deg)}}
@keyframes drift2{to{transform:translate(-8vw,-6vh)}}
.words{position:absolute;inset:0;font:300 clamp(48px,15vw,250px)/.86 var(--display);letter-spacing:-.04em;text-transform:uppercase}
.words .w1,.words .w2{background:linear-gradient(90deg,#FFFFFF 0%,#EDE4FF 45%,#F7C9EC 100%);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;padding:.18em 0;margin-top:-.18em}
.words .w1{position:absolute;left:max(var(--wd-layout-gutter,3vw),calc((100% - 1440px) / 2));margin-left:-.045em;top:calc(12vh + 64px);color:#d9d3e4}
.words .w2{position:absolute;right:max(var(--wd-layout-gutter,3vw),calc((100% - 1440px) / 2));margin-right:-.02em;top:calc(12vh + 64px + .9em);color:#d9d3e4}
.words .plus{position:absolute;left:44vw;top:calc(12vh + 64px + 1em);width:.62em;height:.62em;font-size:clamp(48px,15vw,250px)}
.words .plus::before,.words .plus::after{content:"";position:absolute;background:#EDE4FF;left:50%;top:50%;transform:translate(-50%,-50%)}
.words .plus::before{width:100%;height:.12em}.words .plus::after{width:.12em;height:100%}

/* Header */
.hd{position:fixed;top:env(safe-area-inset-top,0px);left:0;right:0;z-index:20;display:flex;justify-content:space-between;align-items:center;padding:22px var(--pad) 34px;background:linear-gradient(180deg,rgba(20,16,25,.92) 0%,rgba(20,16,25,.6) 60%,rgba(20,16,25,0) 100%)}
.logo{font:500 clamp(20px,1.8vw,26px)/1 var(--display);letter-spacing:-.01em;text-transform:uppercase}
.hd nav{display:flex;align-items:center;gap:28px;font:500 13.5px var(--display);text-transform:uppercase}
.hd nav a.lnk{display:inline-flex;gap:6px;align-items:center;transition:opacity .2s}
.hd nav a.lnk:hover{opacity:.7}
.cta{display:inline-flex;align-items:center;gap:12px;padding:14px 22px;border:1px solid rgba(255,255,255,.35);border-radius:999px;background:rgba(20,16,25,.55);backdrop-filter:blur(8px);font:500 13.5px var(--display);text-transform:uppercase;transition:background .3s,border-color .3s}
.cta:hover{background:rgba(196,168,255,.18);border-color:var(--accent)}
.cta span{transition:transform .4s var(--ease)}.cta:hover span{transform:translateX(4px)}

/* Board */
main{position:relative;z-index:1}
.intro-space{height:calc(52vh + 64px)}
.board{position:relative;width:min(calc(100% - 2 * var(--wd-layout-gutter,3vw)),1440px);margin:0 auto 18vh;padding:0}
.stage{position:relative;transition:height .7s var(--ease)}
.svc{position:absolute;border-radius:var(--wd-panel-radius,32px);background:var(--card);backdrop-filter:blur(22px) saturate(140%);-webkit-backdrop-filter:blur(22px) saturate(140%);overflow:hidden;isolation:isolate;border:1px solid rgba(189,164,255,.13);transition:box-shadow .7s cubic-bezier(.4,0,.2,1);
  transition:left .7s var(--ease),top .7s var(--ease),width .7s var(--ease),height .7s var(--ease),background .3s,box-shadow .7s cubic-bezier(.4,0,.2,1)}
.svc:not(.is-open){cursor:pointer}
/* hover dos boxes de Soluções da home */
.svc::before{content:"";position:absolute;inset:0;border-radius:inherit;z-index:-1;background:linear-gradient(135deg,rgba(124,92,255,.38) 0%,rgba(183,155,255,.22) 45%,rgba(255,143,203,.20) 100%);box-shadow:inset 0 0 0 1px rgba(214,198,255,.35);opacity:0;transition:opacity .7s cubic-bezier(.4,0,.2,1);pointer-events:none}
.svc:hover::before,.svc:focus-within::before,.svc.is-open::before{opacity:1}
.svc:hover,.svc.is-open{box-shadow:0 20px 60px -20px rgba(124,92,255,.55)}
.svc .dots{position:absolute;inset:0;width:100%;height:100%;z-index:0;pointer-events:none;border-radius:inherit}
.svc .head,.svc .content{position:relative;z-index:1}
@media(prefers-reduced-motion:reduce){.svc,.svc::before{transition:none}}
.svc:not(.is-open):hover{background:var(--card-hover)}
.svc .head{position:relative;display:flex;justify-content:space-between;align-items:flex-start;padding:clamp(22px,2.4vw,40px);padding-bottom:0}
.svc .titles{position:relative;flex:1;min-width:0}
.svc .big{margin:0;display:block;font:400 clamp(26px,2.7vw,46px)/1 var(--display);text-transform:uppercase;letter-spacing:-.01em;transition:opacity .3s,transform .5s var(--ease)}
.svc .teaser{display:block;margin-top:14px;font-size:clamp(15px,1.1vw,18px);color:var(--muted);max-width:40ch;transition:opacity .3s}
.svc .small{position:absolute;left:0;top:4px;font:400 clamp(16px,1.4vw,22px) var(--display);text-transform:uppercase;color:var(--muted);opacity:0;transform:translateY(8px);transition:opacity .3s,transform .5s var(--ease)}
.svc.is-open .big,.svc.is-open .teaser{opacity:0;transform:translateY(-8px);pointer-events:none;position:absolute;left:0;right:0;top:0}
.svc.is-open .small{position:relative;top:0;display:block}
.svc.is-open .small{opacity:1;transform:none;transition-delay:.25s}
.svc .icon{width:36px;height:36px;flex:none;display:grid;place-items:center;border-radius:50%;transition:transform .6s var(--ease),background .2s}
.svc .icon{width:56px;height:56px;margin:-8px -8px 0 0}.svc .icon span{display:block;font:300 56px/1 var(--display);color:var(--fg);transform:translateY(-.04em)}
.svc:not(.is-open):hover .icon{transform:rotate(90deg)}
.svc.is-open .icon{transform:rotate(45deg)}
.svc.is-open .icon:hover{background:rgba(255,255,255,.08)}
.svc .content{padding:26px clamp(22px,2.4vw,40px) clamp(24px,2.6vw,44px);opacity:0;transform:translateY(14px);transition:opacity .25s,transform .5s var(--ease)}
.svc.is-open .content{opacity:1;transform:none;transition:opacity .45s .35s,transform .6s .3s var(--ease)}
.svc .content h3{font:400 clamp(24px,2.3vw,40px)/1.08 var(--display);text-transform:uppercase;letter-spacing:-.01em;margin:0 0 12px}
.svc .content p{font-size:clamp(16px,1.3vw,21px);line-height:1.6;opacity:.9;margin:0 0 32px;max-width:60ch}
.see{display:inline-flex;align-items:center;gap:10px;margin-top:6px;padding:12px 18px;border-radius:999px;background:#f2eef8;color:#141019;font:600 12px var(--display);letter-spacing:.06em;text-transform:uppercase;transition:transform .4s var(--ease)}
.see:hover{transform:scale(1.04)}

/* Menu button (bottom-right) */
.menu-btn{position:fixed;right:var(--pad);bottom:calc(24px + env(safe-area-inset-bottom,0px));z-index:30;width:48px;height:48px;border-radius:8px;background:#1d1824;border:1px solid var(--line);display:grid;place-items:center}
.menu-btn i{display:block;width:20px;height:1.6px;background:var(--fg);box-shadow:0 -6px 0 var(--fg),0 6px 0 var(--fg)}
.menu{position:fixed;right:var(--pad);bottom:calc(84px + env(safe-area-inset-bottom,0px));z-index:30;width:220px;padding:16px;border-radius:8px;background:#f2eef8;color:#141019;font:500 13px var(--display);text-transform:uppercase;transform-origin:bottom right;transform:scale(.92);opacity:0;visibility:hidden;transition:transform .35s var(--ease),opacity .25s,visibility .25s}
.menu.on{transform:none;opacity:1;visibility:visible}
.menu a{display:flex;justify-content:space-between;padding:7px 2px;border-bottom:1px solid rgba(20,16,25,.1)}
.menu a:last-child{border:0}
.wa{position:fixed;right:var(--pad);bottom:calc(86px + env(safe-area-inset-bottom,0px));z-index:29;width:48px;height:48px;border-radius:50%;background:#25D366;display:grid;place-items:center;box-shadow:0 10px 30px -8px rgba(37,211,102,.6);transition:opacity .2s}
.wa svg{width:24px;height:24px;fill:#fff}
.menu.on ~ .wa{opacity:0;pointer-events:none}

/* Footer */
footer{position:relative;z-index:1;background:linear-gradient(180deg,rgba(20,16,25,0),var(--bg) 18%);padding:14vh var(--pad) 28px}
.f-big{font:300 clamp(56px,11vw,180px)/.9 var(--display);letter-spacing:-.04em;text-transform:uppercase;margin:0}
.f-big span{background:linear-gradient(90deg,#fff 0%,#EDE4FF 45%,#F7C9EC 100%);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
.f-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:32px;margin-top:56px;padding-top:28px;border-top:1px solid var(--line)}
.f-grid h5{font:500 11px var(--display);letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin:0 0 12px}
.f-grid p{margin:0;color:var(--muted);max-width:36ch;font-size:16px}
.f-grid .help{font:500 20px var(--display);color:var(--fg);margin:0 0 16px}
.f-grid ul{list-style:none;margin:0;padding:0;display:grid;gap:6px;font:500 14px var(--display);text-transform:uppercase}
.legal{margin-top:40px;color:var(--muted);font-size:13px}

@media (max-width:900px){
  .hd nav a.lnk{display:none}
  .cta{padding:11px 16px;font-size:12px}
  .intro-space{height:calc(44vh + 40px)}
  .words .w1{top:calc(14vh + 40px)}.words .w2{top:calc(14vh + 40px + 1em)}.words .plus{left:6vw;top:calc(14vh + 40px + 1.05em)}
  .f-grid{grid-template-columns:1fr}
  .orb{width:120vw;left:-30vw}
}
@media (prefers-reduced-motion:reduce){.orb,.orb2{animation:none}*{transition:none!important;animation:none!important}}

/* Custom cursor (same as the Works page): small dot that follows the mouse; grows on links, shows a label on key items */
.wd-cursor{position:fixed;left:0;top:0;z-index:2147483000;pointer-events:none;width:12px;height:12px;margin:-6px 0 0 -6px;border-radius:50%;background:#F2EEF8;box-shadow:0 0 0 1px rgba(18,19,22,.35);
  transition:width .4s cubic-bezier(.22,1,.36,1),height .4s cubic-bezier(.22,1,.36,1),margin .4s cubic-bezier(.22,1,.36,1),background .3s;display:grid;place-items:center}
.wd-cursor b{font:500 11px/1 "Space Grotesk",Arial,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:#fff;opacity:0;transition:opacity .2s;white-space:nowrap}
.wd-cursor.link{width:40px;height:40px;margin:-20px 0 0 -20px}
.wd-cursor.big{width:96px;height:96px;margin:-48px 0 0 -48px;background:#7C5CFF;mix-blend-mode:normal}
.wd-cursor.big b{opacity:1}
@media not all and (pointer: coarse){.has-wd-cursor,.has-wd-cursor a,.has-wd-cursor button{cursor:none}}
body{margin:0}
:root{--purple:#6025E1;--green:#04CD8F;--wine:#C00252}
/* MENU (copiado da home) */
/* HEADER */
.site-header{position:fixed;top:18px;left:0;right:0;z-index:90;padding:0 clamp(18px,3.2vw,48px);pointer-events:none}
.site-nav{pointer-events:auto;max-width:1240px;margin:0 auto;height:72px;display:flex;align-items:center;gap:34px;padding:0 14px 0 20px;border:1px solid rgba(255,255,255,.10);border-radius:20px;background:rgba(18,19,22,.58);backdrop-filter:blur(22px) saturate(155%);-webkit-backdrop-filter:blur(22px) saturate(155%);box-shadow:0 18px 55px rgba(0,0,0,.18)}
.brand{display:flex;align-items:center;flex:0 0 auto;margin-right:auto}
.brand img{display:block;width:142px;height:auto}
.nav-links{display:flex;align-items:center;gap:32px}
.nav-item,.nav-link{position:relative;display:flex;align-items:center;height:72px;color:#f7f6fb;text-decoration:none;font-size:12px;font-weight:650;letter-spacing:.075em;text-transform:uppercase;white-space:nowrap}
.nav-link:after,.nav-trigger:after{content:"";position:absolute;left:0;right:100%;bottom:19px;height:1px;background:var(--green);transition:right .32s cubic-bezier(.22,1,.36,1)}
.nav-link:hover:after,.nav-item:hover .nav-trigger:after{right:0}
.nav-trigger{appearance:none;border:0;background:none;color:#f7f6fb;font-size:12px;text-transform:uppercase;height:72px;padding:0;cursor:pointer;display:flex;align-items:center;gap:8px;position:relative}
.nav-trigger svg{width:11px;height:11px;transition:transform .3s ease}
.nav-item:hover .nav-trigger svg,.nav-item:focus-within .nav-trigger svg{transform:rotate(180deg)}
.dropdown{position:absolute;top:62px;left:50%;width:min(390px,88vw);padding:12px;border:1px solid rgba(255,255,255,.13);border-radius:18px;background:rgba(26,24,32,.48);backdrop-filter:blur(28px) saturate(170%);-webkit-backdrop-filter:blur(28px) saturate(170%);box-shadow:0 24px 70px rgba(0,0,0,.34);opacity:0;visibility:hidden;transform:translate(-50%,12px) scale(.985);transform-origin:50% 0;transition:opacity .24s ease,transform .34s cubic-bezier(.22,1,.36,1),visibility .24s}
.nav-item:hover .dropdown,.nav-item:focus-within .dropdown{opacity:1;visibility:visible;transform:translate(-50%,0) scale(1)}
.dropdown a{display:grid;grid-template-columns:38px 1fr auto;align-items:center;gap:12px;min-height:66px;padding:12px 14px;border-radius:12px;color:#f7f6fb;text-decoration:none;transition:background .22s ease,transform .22s ease}
.dropdown a:hover{background:rgba(255,255,255,.075);transform:translateX(2px)}
.drop-index{font-size:11px;color:var(--green);letter-spacing:.08em}
.drop-copy strong{display:block;font-size:14px;font-weight:600;letter-spacing:-.01em;text-transform:none}
.drop-copy small{display:block;margin-top:3px;color:#a9b0b0;font-size:12px;font-weight:400;letter-spacing:0;text-transform:none}
.drop-arrow{font-size:18px;color:#8c9594;transition:transform .22s ease,color .22s ease}
.dropdown a:hover .drop-arrow{transform:translateX(3px);color:var(--green)}
.lang{display:flex;align-items:center;gap:6px;color:#9da5a4;font-size:11px;letter-spacing:.08em;text-transform:uppercase;white-space:nowrap}
.lang strong{color:#fff;font-weight:650}
